/**
 * Procedural art for the book completion card. Pure and deterministic: the same book always
 * gets the same card, with no images to host and nothing generated by AI.
 */

export type Genre = 'law' | 'history' | 'wisdom' | 'prophets' | 'gospels' | 'epistles' | 'apocalypse';

export const GENRE_LABEL: Record<Genre, string> = {
  law: 'Lei',
  history: 'História',
  wisdom: 'Poesia e Sabedoria',
  prophets: 'Profetas',
  gospels: 'Evangelhos',
  epistles: 'Cartas',
  apocalypse: 'Profecia final',
};

interface Palette {
  from: string;
  to: string;
  accent: string;
  ink: string;
}

export const PALETTES: Record<Genre, Palette> = {
  law: { from: '#3b2a1a', to: '#8a5a2b', accent: '#f1c27d', ink: '#fff8ec' },
  history: { from: '#14323f', to: '#2f6f73', accent: '#9fe3d0', ink: '#effcf8' },
  wisdom: { from: '#4a2a5e', to: '#a45c8f', accent: '#ffd6a5', ink: '#fff6fb' },
  prophets: { from: '#5a1d12', to: '#c2501f', accent: '#ffd27a', ink: '#fff7ee' },
  gospels: { from: '#13294b', to: '#3a6fb0', accent: '#fde9a8', ink: '#f4f8ff' },
  epistles: { from: '#1d3a2a', to: '#4f8a58', accent: '#d9f0a3', ink: '#f6fff2' },
  apocalypse: { from: '#1a1033', to: '#5a2a8f', accent: '#ffe08a', ink: '#faf5ff' },
};

/** Genre by canonical book order (1 = Gênesis ... 66 = Apocalipse). */
export function genreOf(order: number): Genre {
  if (order <= 5) return 'law';
  if (order <= 17) return 'history';
  if (order <= 22) return 'wisdom';
  if (order <= 39) return 'prophets';
  if (order <= 43) return 'gospels';
  if (order === 44) return 'history'; // Atos
  if (order <= 65) return 'epistles';
  return 'apocalypse';
}

export interface BookCardInput {
  order: number;
  name: string;
  chaptersRead: number;
  chapterCount: number;
  /** null when the learner has not taken any quiz in this book. */
  quizAveragePercent: number | null;
  reflectionCount: number;
  highlightCount: number;
}

export const CARD_WIDTH = 600;
export const CARD_HEIGHT = 840;

function xmlEscape(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Small seeded PRNG so every book gets its own, repeatable pattern.
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pattern(order: number, p: Palette): string {
  const rand = mulberry32(order * 7919 + 13);
  const parts: string[] = [];
  const rays = 10 + (order % 9) * 2;
  for (let i = 0; i < rays; i++) {
    const angle = (360 / rays) * i;
    parts.push(
      `<line x1="300" y1="300" x2="300" y2="-120" stroke="${p.accent}" stroke-opacity="0.07" stroke-width="${2 + (i % 3)}" transform="rotate(${angle.toFixed(2)} 300 300)"/>`,
    );
  }
  for (let i = 0; i < 18; i++) {
    const cx = (rand() * CARD_WIDTH).toFixed(1);
    const cy = (rand() * CARD_HEIGHT).toFixed(1);
    const r = (4 + rand() * 22).toFixed(1);
    parts.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${p.accent}" fill-opacity="${(0.04 + rand() * 0.08).toFixed(3)}"/>`);
  }
  return parts.join('');
}

// Symbols are drawn around (300, 300) in a ~200px box.
function symbol(genre: Genre, p: Palette): string {
  const stroke = `stroke="${p.accent}" stroke-width="6" stroke-linecap="round" stroke-linejoin="round" fill="none"`;
  switch (genre) {
    case 'law':
      return `<rect x="205" y="215" width="80" height="170" rx="38" ${stroke}/><rect x="315" y="215" width="80" height="170" rx="38" ${stroke}/><path d="M225 270h40M225 295h40M225 320h40M335 270h40M335 295h40M335 320h40" ${stroke}/>`;
    case 'history':
      return `<rect x="225" y="225" width="150" height="150" rx="8" ${stroke}/><circle cx="225" cy="225" r="16" ${stroke}/><circle cx="375" cy="375" r="16" ${stroke}/><path d="M255 275h90M255 305h90M255 335h60" ${stroke}/>`;
    case 'wisdom':
      return `<circle cx="300" cy="300" r="52" ${stroke}/>${Array.from({ length: 12 }, (_, i) => `<line x1="300" y1="215" x2="300" y2="238" ${stroke} transform="rotate(${i * 30} 300 300)"/>`).join('')}`;
    case 'prophets':
      return `<path d="M300 205c30 45 70 70 70 125a70 70 0 0 1-140 0c0-35 22-50 36-78 8 22 22 28 34-47z" ${stroke}/><path d="M300 290c14 22 30 32 30 55a30 30 0 0 1-60 0c0-16 10-24 30-55z" ${stroke}/>`;
    case 'gospels':
      return `<path d="M300 205v190M225 275h150" ${stroke}/><circle cx="300" cy="275" r="92" ${stroke} stroke-opacity="0.55"/>`;
    case 'epistles':
      return `<rect x="205" y="245" width="190" height="125" rx="10" ${stroke}/><path d="M205 255l95 70 95-70" ${stroke}/>`;
    case 'apocalypse':
      return `${Array.from({ length: 7 }, (_, i) => {
        const a = (Math.PI * 2 * i) / 7 - Math.PI / 2;
        return `<circle cx="${(300 + Math.cos(a) * 85).toFixed(1)}" cy="${(300 + Math.sin(a) * 85).toFixed(1)}" r="14" fill="${p.accent}"/>`;
      }).join('')}<circle cx="300" cy="300" r="26" ${stroke}/>`;
  }
}

function stat(y: number, label: string, value: string, p: Palette): string {
  return `<text x="60" y="${y}" font-size="22" fill="${p.ink}" fill-opacity="0.75">${xmlEscape(label)}</text><text x="540" y="${y}" font-size="26" font-weight="700" fill="${p.ink}" text-anchor="end">${xmlEscape(value)}</text><line x1="60" y1="${y + 14}" x2="540" y2="${y + 14}" stroke="${p.ink}" stroke-opacity="0.15"/>`;
}

/** The whole card as a standalone SVG string (also used to export a PNG). */
export function buildBookCardSvg(input: BookCardInput): string {
  const genre = genreOf(input.order);
  const p = PALETTES[genre];
  const completed = input.chapterCount > 0 && input.chaptersRead >= input.chapterCount;
  const badge = completed ? 'CONCLUÍDO' : `EM ANDAMENTO · ${input.chaptersRead}/${input.chapterCount}`;
  const quiz = input.quizAveragePercent === null ? '—' : `${input.quizAveragePercent}%`;
  const font = `font-family="Georgia, 'Times New Roman', serif"`;
  const titleSize = input.name.length > 14 ? 48 : 60;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}" viewBox="0 0 ${CARD_WIDTH} ${CARD_HEIGHT}" role="img" aria-label="Cartão de conclusão: ${xmlEscape(input.name)}" ${font}>
<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${p.from}"/><stop offset="1" stop-color="${p.to}"/></linearGradient></defs>
<rect width="${CARD_WIDTH}" height="${CARD_HEIGHT}" rx="28" fill="url(#bg)"/>
<g>${pattern(input.order, p)}</g>
<rect x="18" y="18" width="${CARD_WIDTH - 36}" height="${CARD_HEIGHT - 36}" rx="20" fill="none" stroke="${p.accent}" stroke-opacity="0.5" stroke-width="2"/>
<g>${symbol(genre, p)}</g>
<text x="300" y="470" font-size="18" letter-spacing="4" fill="${p.accent}" text-anchor="middle">${xmlEscape(GENRE_LABEL[genre].toUpperCase())}</text>
<text x="300" y="535" font-size="${titleSize}" font-weight="700" fill="${p.ink}" text-anchor="middle">${xmlEscape(input.name)}</text>
<rect x="${completed ? 205 : 150}" y="560" width="${completed ? 190 : 300}" height="38" rx="19" fill="${p.accent}"/>
<text x="300" y="586" font-size="17" font-weight="700" letter-spacing="2" fill="${p.from}" text-anchor="middle">${xmlEscape(badge)}</text>
${stat(655, 'Capítulos lidos', `${input.chaptersRead}/${input.chapterCount}`, p)}
${stat(705, 'Média nos quizzes', quiz, p)}
${stat(755, 'Explicações escritas', String(input.reflectionCount), p)}
${stat(805, 'Versículos destacados', String(input.highlightCount), p)}
</svg>`;
}
